def cheapestExactWalk(n, roads, src, dst, k):
    NOPATH = 1000000000
    INF = float('inf')
    cur = [INF] * n
    cur[src] = 0
    for _ in range(k):
        nxt = [INF] * n
        for u, v, t in roads:
            if cur[u] != INF and cur[u] + t < nxt[v]:
                nxt[v] = cur[u] + t
        cur = nxt
    return NOPATH if cur[dst] == INF else cur[dst]
